function validate([m, n, ops]) {
  if (!Number.isInteger(m) || !Number.isInteger(n) || m < 1 || n < 1 || m > 40000 || n > 40000) return 'm and n are between 1 and 40000.';
  if (!Array.isArray(ops) || ops.length > 10000) return 'ops holds at most 10000 operations.';
  for (const op of ops) {
    if (!Array.isArray(op) || op.length !== 2) return 'Each operation is an [a, b] pair.';
    if (!Number.isInteger(op[0]) || op[0] < 1 || op[0] > m) return 'Each a is between 1 and m.';
    if (!Number.isInteger(op[1]) || op[1] < 1 || op[1] > n) return 'Each b is between 1 and n.';
  }
  return null;
}

