function maxCount(m, n, ops) {
  // Cut the matrix into blocks at every operation edge; all cells of a block get the same value.
  const rowCuts = [...new Set([m, ...ops.map(op => op[0])])].sort((p, q) => p - q);
  const colCuts = [...new Set([n, ...ops.map(op => op[1])])].sort((p, q) => p - q);
  let top = -1;
  let count = 0;
  for (let i = 0; i < rowCuts.length; i++) {
    for (let j = 0; j < colCuts.length; j++) {
      const x = rowCuts[i] - 1;
      const y = colCuts[j] - 1;
      const value = ops.filter(([a, b]) => x < a && y < b).length;
      const cells = (rowCuts[i] - (i ? rowCuts[i - 1] : 0)) * (colCuts[j] - (j ? colCuts[j - 1] : 0));
      if (value > top) { top = value; count = 0; }
      if (value === top) count += cells;
    }
  }
  return count;
}

