function generate(rand, size) {
  if (size === 'large') {
    const m = 20000 + Math.floor(rand() * 20001);
    const n = 20000 + Math.floor(rand() * 20001);
    const spreadRows = Math.floor(rand() * m);
    const spreadCols = Math.floor(rand() * n);
    const ops = Array.from({ length: 2000 }, () => [m - Math.floor(rand() * spreadRows), n - Math.floor(rand() * spreadCols)]);
    return [m, n, ops];
  }
  const m = 1 + Math.floor(rand() * 6);
  const n = 1 + Math.floor(rand() * 6);
  const count = Math.floor(rand() * 7);
  const ops = Array.from({ length: count }, () => [1 + Math.floor(rand() * m), 1 + Math.floor(rand() * n)]);
  return [m, n, ops];
}
